/* KPC app: ❓ HELP (Opus, Nov 6; Brandon: 'a help screen would be nice too').
   - ❓ in the top bar on EVERY screen: help for the screen you are on, with ALL HELP / SETUP WIZARD / SOMETHING NOT WORKING.
   - the ❓ HELP page: search box, every topic, a setup guide per radio (CAT, baud, USB sound, the DATA menu), the troubleshooter,
     the radios list (which controls each one takes, and which have been checked on a real radio), and 📝 WORKS ON MY RADIO.
   - 🧙 RADIO SETUP WIZARD: pick the radio → set its menus → plug in + connect → does the frequency match? → sound → done.
   - 📝 WORKS ON MY RADIO: tick what worked and what did not; the report is copied / shared / saved, and kept here (kpcAppWorks) so the
     radios list shows it. Send it to the club so the radio can be marked 'checked'. */
(function (G) {
  'use strict';
  const AP = G.KPCApp, $ = id => document.getElementById(id); if (!AP) return;
  const esc = AP.esc, K = G.KPCCat;
  const LS = (k, d) => { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : d; } catch (e) { return d; } };
  const SV = (k, v) => { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} };
  const WORKS = LS('kpcAppWorks', {});

  /* ================================================================ TOPICS (screen = the screen it belongs to) */
  const T = [
    { id: 'logs', s: 'logs', t: 'My logs', k: 'logs park activation hunt event new log open', h: 'Every log you keep: one per park activation, hunting day, contest or event. Tap one to open it; <b>+ NEW LOG</b> starts another. Contacts always land in the open log, and EVERY CONTACT shows them all.' },
    { id: 'log', s: 'log', t: 'Logging a contact', k: 'log call enter rst report dupe band mode frequency dock ft8 -10', h: 'Reports left empty: 59 on phone, 599 on CW, -10 / -10 for a typed-in FT8 / FT4 contact. Type the call in the CALL box at the bottom and press ⬆ (or Enter). Band, mode and frequency come from the radio when it is connected, or tap them in the dock. RST boxes fill themselves if you leave them empty. Type <b>HELP</b> in the CALL box for the typed commands (20M, CW, 14.074 …). Several calls with commas log one contact each.' },
    { id: 'digi', s: 'digi', t: 'FT8 / FT4 and the digital modes', k: 'ft8 ft4 digi decode cq auto run hunt waterfall tx level', h: 'Press START (sound on), pick FT8 or FT4, and decodes scroll in. Tap a station to call it, or 📣 CQ. ENABLE TX lets it transmit; HALT stops at once. The slim <b>band strip</b> at the top shows who is spotted on this band (and the IC-7300 / 705 / 9700 / 7610 / 905 RF scope under it); tap a call there to go to it. Keep the radio\'s ALC low: set the TX level so ALC barely moves.' },
    { id: 'hound', s: 'digi', t: '🦊 Fox & Hound (FT8 DXpeditions)', k: 'fox hound dxpedition f/h superfox rare dx ft8 pileup', h: 'Big DXpeditions run FT8 as a <b>Fox</b>, working many callers (<b>Hounds</b>) at once, below 1000 Hz and away from the usual FT8 frequencies (the DX spots and the DXpedition\'s web page give the dial). Tap the Fox\'s line: <b>🦊 HOUND</b> turns on by itself, you call above 1000 Hz with your grid, and when the Fox sends your report the app answers R+report near the Fox\'s frequency. The Fox\'s RR73 logs it; Hounds send no 73. 🦊 marks a Fox in the decode list. Turn HOUND off for normal FT8. <b>SuperFox</b> (the newer signed kind) can\'t be decoded here yet: use WSJT-X for those.' },
    { id: 'spots', s: 'spots', t: 'Spots', k: 'spots pota sota cluster rbn filter tune', h: 'Live spots from POTA, SOTA, the DX cluster and the skimmers. Tap a spot: the radio tunes there and the CALL box fills. Filters at the top pick bands, modes and programs.' },
    { id: 'logcheck', s: 'log', t: '✅ Check & save for POTA', k: 'check log adif pota qrz upload file valid activation 10 contacts fix dupes rates export', h: 'Tap <b>✅ CHECK</b> on the LOG screen (or STATION → Log files). It checks the log on the screen: calls, date and time, band, mode, your station call, park numbers, doubles, and the 10 contacts per park per UTC day POTA needs. <b>FIX ALL</b> fixes the safe ones (band from the frequency, your call as the station call, capitals); nothing is deleted. <b>SAVE FOR POTA</b> makes one file per park and call (or per day, or one file) named the way POTA names them, then <b>POTA UPLOAD PAGE</b> takes you to Log Uploads. For the full editor, open the website checker and load the saved file.' },
    { id: 'cond', s: 'spots', t: '☀ Conditions (weather, space weather, band plan)', k: 'conditions weather lightning thunder storm space weather solar flux kp sfi a index xray bz solar wind band plan privileges class tech general extra noaa alerts plan activation greyline sunset', h: 'SPOTS has two tabs: <b>📍 SPOTS</b> and <b>☀ CONDITIONS</b>. CONDITIONS shows the <b>weather here</b> (National Weather Service, US: temperature, wind, rain chance, thunderstorms in the forecast; a thunderstorm or tornado <b>warning</b> also shows in red on LOG and as an alert), sunrise, sunset and the grey line, <b>space weather</b> from NOAA (tap a tile for what it means), <b>where should I start</b> (a rule of thumb plus how busy each band is on SPOTS), the <b>band plan</b> for your licence class (tap a part to tune there; always check the full FCC chart), the next 3 days for <b>planning an activation</b>, and <b>alerts</b>. The forecast is not a lightning detector: if you hear thunder, get the antenna down. 🗺 DAY / NIGHT MAP is at the bottom.' },
    { id: 'autospot', s: 'spots', t: '📣 Spot me (activating)', k: 'spot me auto spot keep me spotted activator pota wwff sota relay', h: 'When you activate a park, the app offers to spot you on POTA after your first contact, and again when you change band, mode or frequency. Nothing goes out until you press YES. <b>KEEP ME SPOTTED</b> (10, 15 or 20 min) re-spots you only while you keep logging on that frequency; it stops when you go quiet or QSY. The app sends at most 1 spot every 5 minutes and 4 an hour by itself. With a WWFF or SOTA reference it opens their spot page (they do not take spots from apps). The 📣 SPOT ME chip on LOG shows only when a park number is set. Settings: STATION → Log files → 📣 AUTO SPOT ME. POTA spots come through the club\'s spot relay, with POTA itself as the backup.' },
    { id: 'split', s: 'spots', t: '↗ Split (rare DX listening up)', k: 'split up dn qsx listening vfo b pileup rare dx ssb cw', h: 'When a spot says where the DX listens (<b>UP 5</b>, <b>up 5-10</b>, <b>DN 2</b>, <b>QSX 14.205</b>), it shows <b>↗ SPLIT</b>. Tap it: the radio goes to the DX on VFO A, VFO B goes where they listen and SPLIT turns on, so you transmit there. The next ordinary spot turns split off again. No CAT, or a radio that can\'t, gets a note with the frequency to set by hand. No hint in the spot? Nothing can know for sure where the DX listens: listen for who they answer, and on a scope radio look for the pileup above them.' },
    { id: 'ops', s: 'spots', t: '👥 Several ops at one park', k: 'two ops multi op same park team activation calls one contact each', h: 'When two or more operators are spotted at the same park within 1 kHz, tapping one spot fills in all their calls ("A, B"): pressing ⬆ logs one contact each. Spaces or commas both split calls.' },
    { id: 'radio', s: 'radio', t: 'The RADIO screen', k: 'radio vfo frequency band mode filter width nb nr notch power mic meters tune', h: 'Run the radio from here: frequency (wheel, arrows, − +, tap to type), band and mode buttons, filter width, NB / NR / NOTCH, RF power, mic gain, the meters, 🔧 TUNE, radio on / off and 🎙 HOLD TO TALK. A band button goes back to the last frequency you used on that band (📍 band memory).' },
    { id: 'more', s: 'radio', t: '🎛 More controls', k: 'if shift pbt passband nr level nb level agc att attenuator preamp ipo amp contour apf notch split rit xit clarifier vfo swap a=b keyer speed break-in', h: 'Under the meters: IF SHIFT, NR and NB level, AGC, ATT, PRE / IPO, CONTOUR, APF, MANUAL NOTCH, SPLIT, A ⇄ B, A = B, RIT / XIT with the offset, keyer speed and break-in. Only what YOUR radio takes over CAT shows. The radio does not tell the app when you turn its own knobs, so these show what was sent last. If one does nothing on your radio, send a 📝 WORKS ON MY RADIO report.' },
    { id: 'tune', s: 'radio', t: '🔧 Tune and the SWR guard', k: 'tune tuner atu swr mismatch antenna high swr warning power', h: '🔧 TUNE starts the radio\'s own antenna tuner. It always asks first because the radio transmits a carrier; afterwards the app tells you the SWR it saw. The <b>SWR guard</b> watches the SWR while you transmit: over the limit (2 : 1, 2.5 : 1 or 3 : 1) it warns you, and can also turn the power down to 25 % or stop transmitting (🎛 MORE CONTROLS → Safety). The SWR from the radio\'s meter is close, not exact.' },
    { id: 'station', s: 'station', t: 'Station settings', k: 'station call grid radio cat sound card ptt vox backup digirig rts dtr key line', h: 'Your call, grid and park; MY RADIO and CONNECT RADIO; the sound card; how the radio is keyed (CAT command, VOX, or on a computer the RTS or DTR line of the radio\'s cable, which is how a Digirig keys; CW can also use its own DTR / RTS key line); uploads, backups and the extras (contesting, skimmers, scope, rotator, listening clean-up). Use the search box at the top of STATION to jump to a setting.' },
    { id: 'sdr', s: 'radio', t: '📻 The black radio page (SIMPLE / FULL, power, memories)', k: 'radio page sdr black power button simple full vfo b split clar clarifier rit xit wpm memories m1 band plan lit vox comp monitor', h: 'The RADIO tab is a black front panel. <b>⏻</b> glows green when the radio is on and talking to the app (tap it to turn the radio off, or to connect / turn it on); the whole page dims when it is not. <b>SIMPLE</b> shows frequency, bands, modes, the waterfall, meters and talk; <b>FULL</b> shows every control your radio takes over CAT (IF shift, NR / NB, notch, contour, APF, AGC, ATT, preamp, VOX, COMP, MONITOR, break-in…). Under the frequency: the <b>band plan</b> for your licence class with a red mark where you are, <b>VFO B</b>, A ⇄ B, A = B, SPLIT, CLAR (clarifier / RIT) and XIT with − / + and CLEAR, and keyer <b>WPM</b>. <b>M1–M6</b>: tap an empty one to store where you are, tap a full one to go back; ✎ STORE then a button stores over it. Band buttons have a coloured line: green = open today, amber = fair, grey = closed (a rule of thumb).' },
    { id: 'ft710scope', s: 'radio', t: '🌊 The FT-710\'s own waterfall (Windows app)', k: 'ft710 ft-710 scope waterfall panadapter ft4222 scu-lan10 python span yaesu', h: 'The FT-710 sends its real scope on a second USB connection. On the Windows app: 1) radio menu OPERATION SETTING → GENERAL → <b>SCU-LAN10 = ON</b>; 2) install Python 3 from python.org (tick Add to PATH); 3) in a Command Prompt: <b>py -m pip install ft4222</b>; 4) close any other scope program; 5) pick FT-710 as your radio and open RADIO. The waterfall then shows the band like the radio\'s own screen. Set the radio\'s scope to CENTER and pick the same <b>RADIO SPAN</b> in the app (20 / 50 / 100 / 200 / 500 kHz). Phones on the remote link see it too. Not on Android yet.' },
    { id: 'trip', s: 'map', t: '🚗 Trip planner (MAP)', k: 'trip planner route plan parks map near me directions gpx csv start here nearest order offline', h: 'MAP has two tabs: <b>🗺 CONTACTS</b> and <b>🚗 TRIP PLANNER</b>. Pick a state on the device, search, or <b>📍 NEAR ME</b>; <b>NOT ACTIVATED BY ME</b> hides the ones you have done. <b>+ ADD</b> puts a park in the trip. The trip: ↑ ↓ to move a stop, ⚡ NEAREST-NEXT to re-order from where you are, 🧭 DIRECTIONS for the whole trip in your maps app, 🌲 START HERE makes that park MY PARK and opens LOG, ⬇ GPX / CSV, 📤 SHARE. It uses the park lists on this device, so it works with no signal.' },
    { id: 'parklist', s: 'station', t: '🌲 Park list on the device (📍 NEAR ME)', k: 'park list offline download state update near me my park number pick nearby', h: 'The app keeps each state\'s parks on the device (STATION → Parks), so they work with no signal. It checks about once a day, when you have signal, whether the KPC website has a newer list and only downloads a state that changed. The first time, it gets the state you are in by itself. Every <b>MY PARK NUMBER</b> box has <b>📍 NEAR ME</b>: the parks around you (the one you are inside first); tap one to add it.' },
    { id: 'field', s: 'station', t: '🏕 Ready for the field + 📴 OFFLINE', k: 'offline field ready no signal park trip forecast backup', h: 'STATION → Parks → <b>🏕 GET READY FOR THE FIELD</b>, while you still have signal: it gets the parks for your state, your park and your trip, saves the forecast and space weather, checks the clock, and saves a copy of your log + settings. Spots are not saved (they would be old). <b>📴 OFFLINE</b> shows in the top bar whenever there is no signal; logging, FT8, the park lists and the trip all keep working.' },
    { id: 'hear', s: 'spots', t: '👂 Can I hear them?', k: 'hear alert need park audible decode ft8 cw', h: 'An alert only when a park you still need today is spotted AND your own radio hears it: your FT8 / FT4 decoder decoded that call (with its report), or your CW decoder copied it, in the last 3 minutes. So you only chase spots you can work. Turn it off in the alerts list (👂).' },
    { id: 'inpark', s: 'log', t: '📍 In the park? (on LOG)', k: 'in the park gps outline outside line activating', h: 'While you activate with a park number set, a phone checks its GPS against the park\'s outline every 5 minutes: <b>📍 IN US-1234</b>, or <b>📍 OUTSIDE</b> with how far you are from the line. Approximate outlines say so. Needs the state\'s parks on the device.' },
    { id: 'txsafe', s: 'station', t: '⏱ Longest transmission (safety stop)', k: 'stuck transmit ptt keyed unkey safety timer longest transmission stop', h: 'STATION → Radio control → <b>LONGEST TRANSMISSION</b> (3 min unless you change it). Anything that keys the radio (voice keyer, hold to talk, TUNE, FreeDV, a phone on the remote link) is unkeyed after that long, with a red note. After every unkey the app asks the radio whether it really went back to receive and sends the unkey again if not; if it still says transmit you get a red warning: press the radio\'s own MOX / PTT or turn the power down.' },
    { id: 'notsaved', s: 'log', t: '⚠ NOT SAVED (red bar on LOG)', k: 'not saved storage full lost contacts save log file', h: 'The phone or PC refused to store a contact (storage full). The contact is still in the app\'s memory: press <b>SAVE THE KPC LOG FILE NOW</b>, free up space, then TRY AGAIN. A restore (KPC log file, backup or ADIF) also offers to bring back contacts that were deleted or CLEARed.' },
    { id: 'autobtn', s: 'digi', t: '🔁 AUTO RUN / AUTO HUNT (hidden)', k: 'auto run hunt both cq automatic hidden limit minutes', h: 'The AUTO RUN, AUTO HUNT and AUTO BOTH buttons are hidden unless you switch them on: ⚙ FT8 → <b>Show the AUTO RUN / AUTO HUNT / AUTO BOTH buttons</b>. They run 5 to 60 minutes (30 to start), then stop by themselves. Stay at the radio while they run.' },
    { id: 'catlog', s: 'station', t: '📜 Radio log (when the radio does not do what it should)', k: 'radio log cat log verbose commands debug not working tune wrong frequency', h: 'STATION → Radio control → <b>📜 RADIO LOG</b> shows the last 200 commands the app sent the radio (&gt;) and what it answered (&lt;), live. If a radio misbehaves, press COPY and send it with ⚙ the app report (it carries the last 40 lines too). Nothing secret is in it.' },
    { id: 'kiwi', s: 'radio', t: '📻 Web radio (KiwiSDR)', k: 'kiwi kiwisdr web sdr receiver listen online no radio remote receiver', h: 'Listen to the band through someone else\'s receiver on the internet: RADIO → 📻 WEB RADIO (or STATION → 📻 RADIO & SOUND). Pick one near you (or far away, to hear what they hear), CONNECT, then pick the band and mode. With <b>FOLLOW SPOT TAPS</b> on, tapping a spot tunes it too. It is listening only (you can\'t transmit through it), the sound is a second or so behind, and the receiver belongs to someone else: one connection, and disconnect when you are done. Many receivers kick you off after an hour or when busy.' },
    { id: 'contest', s: 'contest', t: 'Contesting', k: 'contest field day wfd sweepstakes cqww wpx naqp sprint qso party exchange dupe mult cabrillo score', h: 'Pick the contest and fill MY exchange, then 📒 OPEN THE CONTEST LOG. Log right at the top of the 🏆 CONTEST screen (CALL + the exchange boxes + LOG, Enter logs, Esc wipes) or from the LOG screen. The line says ⛔ DUPE, ⭐ NEW mult or ✓ needed before you log. SAVE CABRILLO makes the file every contest takes.' },
    { id: 'net', s: 'contest', t: 'Field Day / multi-op network', k: 'network multi op field day share log pc hub phones gota', h: 'One PC is the hub; other PCs and phones join with the pair code (STATION → REMOTE LINK, "share the log only"). Every contact goes to every station, dupes are checked across all of them, and it all works with no internet on the site\'s own Wi-Fi.' },
    { id: 'cos', s: 'contest', t: 'Live score', k: 'contest online scoreboard live score cos', h: 'Turn on the live score with your contestonlinescore.com login: the score goes up every 2 minutes while there is internet, and waits when there is not.' },
    { id: 'skim', s: 'contest', t: 'Skimmers and the band map', k: 'skimmer rbn reverse beacon who hears me region band map waterfall', h: 'The Reverse Beacon Network skimmers in the US and Canada, by region. WHO HEARS ME lists the skimmers that heard your CQ and how loud. The band map shows who is where: gold = new mult, green = needed, grey = dupe, red = a call that is probably busted.' },
    { id: 'tabs', s: 'station', t: 'Finding a setting (the STATION tabs)', k: 'station tabs settings find where group me radio sound log parks alerts remote help all', h: 'STATION is split into tabs along the top: <b>👤 ME</b> (call, grid, park, power, the look), <b>📻 RADIO & SOUND</b> (radio, CAT, sound card, levels, rotator), <b>📋 LOG</b> (log files, uploads, contesting, moving to a new phone), <b>🌲 PARKS & ALERTS</b>, <b>🔗 REMOTE</b>, <b>❓ HELP</b> and <b>ALL</b> (everything on one page). The tab you used last opens next time. 🔍 <b>Find a setting</b> always searches every tab. Long explanations are folded under <b>ℹ️ HOW THIS WORKS</b>: tap to read.' },
    { id: 'talk', s: 'radio', t: '🎙 Hold to talk and the voice sound', k: 'talk voice mic microphone ptt hold natural punch contest preset keyer', h: 'On the PC, <b>🎙 HOLD TO TALK</b> keys the radio first and then opens the computer\'s mic (it stays warm for 60 s, so the next press is instant). The strip under it shapes your voice: <b>NATURAL</b>, <b>PUNCH</b> (cuts through) or <b>CONTEST</b> (strongest). The radio\'s MOD SOURCE must be USB / REAR so it takes the computer\'s sound.' },
    { id: 'dv', s: 'radio', t: '🗣 Digital voice (FreeDV)', k: 'dv digital voice freedv 700d 700e 1600 codec2 codec sync snr squelch text callsign', h: 'RADIO → 🗣 DIGITAL VOICE: pick <b>700D</b> (the usual HF mode, works in weak, fading signals), <b>700E</b> (better in fast fading) or <b>1600</b> (needs a stronger signal). Both stations need the <b>same mode and sideband</b>: USB, LSB on 40 m and below. Radio: speech processor OFF, TX level so the ALC barely moves. Then 🎙 HOLD TO TALK sends digital voice (the voice shaping is bypassed) and 🔊 HEAR HERE plays the decoded voice when the SYNC light is green, the plain radio sound when not (or nothing, with MUTE WHEN NOT IN SYNC). SQUELCH = only play DV above that SNR. Your call goes out on the text channel and theirs shows under HEARD. It needs the PC doing the radio\'s sound; not on the phone app or over the remote link. <b>ANALOG ⇄ DIGITAL</b> flips back and forth.' },
    { id: 'iphone', s: 'remote', t: '📱 iPhone and iPad', k: 'iphone ipad safari apple tailscale phone page remote', h: 'There is no KPC app for iPhone: the PC with the radio hands out the app\'s own page. At home open <b>http://&lt;PC address&gt;:8731/phone/</b> in Safari (listen and run the radio). For talking, and from away, use the PC\'s Tailscale https address. Add it to the Home Screen to use it like an app. The sound stops when the screen locks: that is Apple\'s rule for web pages.' },
    { id: 'scope', s: 'station', t: 'The RF scope', k: 'scope spectrum waterfall ic-7300 ic-705 ic-9700 ic-7610 ic-905 audio', h: 'Icom IC-7300 / 705 / 9700 / 7610 / 905 send their own scope over the USB cable: the app shows it on the RADIO screen and under the band maps. Other radios get the AUDIO picture (what the sound card hears). The Yaesu FT-710 scope needs a special driver the app cannot use.' },
    { id: 'rotor', s: 'station', t: 'Rotator', k: 'rotator rotor beam heading rotctld hamlib long path', h: 'Through Hamlib rotctld (Windows app): TURN, STOP, follow a spot\'s heading, long path, and a beam offset.' },
    { id: 'nr', s: 'station', t: 'Listening clean-up (noise reduction)', k: 'noise reduction nr blanker notch filter listening clean up cw peak apf pitch', h: 'Cleans up what you HEAR from the radio here (HEAR THE RADIO HERE and the phone): noise reduction, a noise blanker for clicks, an automatic notch for carriers and a band-pass filter. The decoders always get the untouched sound. With FILTER on CW you also get <b>CW PITCH</b> (500 to 800, match your radio\'s pitch) and <b>🎯 PEAK</b>: a narrow boost right on the pitch, so the one station you are copying stands out.' },
    { id: 'remote', s: 'remote', t: 'Remote: the radio from a phone', k: 'remote phone pc pair tailscale wifi voice audio', h: 'The PC with the radio is the base. Pair the phone with the code on the PC (same Wi-Fi, or Tailscale away from home). The phone gets the frequency, mode, meters, TUNE (it asks first), voice both ways and FT8.' },
    { id: 'backup', s: 'station', t: 'Backups', k: 'backup restore move phone new computer', h: 'STATION → BACKUP saves your log and every setting in one file; RESTORE puts it back on any device.' },
    { id: 'lite', s: '', t: 'KPC Lite', k: 'lite apk smaller', h: 'KPC Lite is the same app with fewer modes (FT8 + FT4 only, no remote link). Contesting, skimmers, the scope, the rotator, the clean-up, 🎛 more controls and this help are all in Lite too: turn them on in STATION.' },
    /* Nov 18 (Opus, 0.9.6 help pass): the 0.9.6 additions + the screens that had no topic. a: 1 = shown in the ❓ help of EVERY screen. */
    { id: 'onair', s: '', a: 1, t: '🔴 ON AIR and ■ STOP ALL', k: 'on air stop all esc transmit transmitting keyed stuck emergency red strip', h: 'Whenever the app makes the radio transmit (FT8, CW, your voice, the voice keyer, TUNE, or the PC\'s radio when you are on the remote link), a slim red <b>ON AIR</b> strip shows at the top of every screen, with a timer and what is sending. <b>■ STOP ALL</b> on the strip stops everything at once and puts the radio back to receive. On a PC the <b>Esc</b> key does the same. On a phone on the remote link, STOP ALL stops the PC\'s radio, whoever is talking. After STOP ALL (or HALT) on FT8 / FT4, nothing is sent again until YOU press 📣 CQ or ENABLE TX, or tap a station: a station answering will not switch transmit back on. If the radio still stays in transmit, press its own PTT / MOX or turn it off, then send a 📋 report (STATION → Help &amp; about).' },
    { id: 'levels', s: 'station', t: '🎚 Set my levels (ALC helper)', k: 'alc level levels tx level power helper too loud splatter dirty wide voice level test tone', h: 'STATION → Sound → <b>🎚 SET MY LEVELS</b>. Pick <b>FT8 / DIGITAL</b> or <b>MY VOICE (SSB)</b>. For digital, press <b>▶ SEND A TEST TONE</b> (10 seconds; use a dummy load or a clear frequency). For voice, hold 🎙 HOLD TO TALK on the RADIO screen and talk normally. The helper reads the radio\'s ALC and power and tells you in words: 🟢 good, 🟡 a little high, 🔴 too much. Press − or + until it says 🟢. The aim is full power with the ALC barely moving; too much ALC makes a wide, dirty signal. If the radio does not send its meters to the app (Android while transmitting, and some radios), watch the ALC on the radio itself.' },
    { id: 'vmon', s: 'station', t: '🎧 Hear my processed voice', k: 'monitor hear my voice processed shaper limiter headphones listen to myself', h: 'STATION → Sound → tick <b>🎧 Hear my processed voice while I talk</b>. While you hold to talk you hear what really goes to the radio: after the voice shaper, the limiter and the 2.8 kHz band limit. It plays on the HEAR THE RADIO HERE speakers, so turn that on too. Use headphones, or the speaker will feed back into the mic.' },
    { id: 'setup', s: 'station', t: '🧭 First-time setup, step by step', k: 'setup set up first run first time wizard start new install call grid park radio sound', h: 'The first time the app opens with no call sign, it walks you through 5 short steps: your call sign, your grid square (📍 USE MY LOCATION can fill it in), hunting or activating (and your park), your radio, and the sound. Each step fills the same boxes as STATION, so you can change anything later. To run it again: STATION → <b>🧭 SET UP STEP BY STEP</b>. For the radio\'s own menus, the <b>🧙 RADIO SETUP WIZARD</b> on the HELP page goes further.' },
    { id: 'looks', s: 'station', t: '🎨 Looks: NIGHT, SUNLIGHT and the rest', k: 'look looks theme night red sunlight sun bright outdoor dark light lodge forest colours colors', h: 'STATION → Look. <b>🔴 NIGHT</b> is red on black: easy on the eyes in a dark tent or car, and it keeps your night vision. <b>🌞 SUNLIGHT</b> is black on white, for a screen in bright sun. <b>🔥 CABIN LODGE</b>, <b>🌲 FOREST NIGHT</b> and <b>☀️ LIGHT</b> are the everyday looks. The app remembers your pick.' },
    { id: 'map', s: 'map', t: '🗺 The MAP screen', k: 'map qso map contacts lines distance bearing satellite offline world', h: 'MAP has two tabs. <b>🗺 CONTACTS</b> draws each contact in the open log (or today, or all) as a line from where you were to where they were, coloured by band, with a list of distance and direction beside it. Tap a line or a dot for the contact\'s card (✏️ FIX IT opens the edit sheet). With signal you get satellite pictures with streets; with no signal the app draws its own built-in world map, so it still works in the field. <b>🚗 TRIP PLANNER</b> is the other tab (it has its own help).' },
    { id: 'aprs', s: 'digi', t: '📡 APRS', k: 'aprs beacon position message igate digipeater tnc 144.390 packet', h: 'DIGI → <b>APRS</b> sends and hears APRS through the sound card (no TNC needed), or through a Bluetooth / USB TNC (📶 TNC). <b>📡 BEACON NOW</b> sends your position; how often is set in ⚙ (AUTO when mobile beacons more often while you move). <b>✉ MESSAGE</b> sends a message to another station. <b>🗺 MAP</b> shows who you heard and how their signal reached you. In the US the frequency is 144.390 MHz FM. A practice call like K4TEST can listen but never transmits.' },
    { id: 'modes5', s: 'digi', t: 'CW, RTTY, HELL and SSTV', k: 'cw morse rtty hellschreiber hell sstv picture decoder keyer', h: 'Pick the chip at the top of DIGI, then 🎧 START LISTENING. <b>CW</b> decodes Morse; type to send (through the radio\'s own keyer, a DTR / RTS key line, or a tone), or ✋ TAP TO KEY by hand. <b>RTTY</b> (45.45, 50 or 75 baud) only prints while a real signal is there. <b>HELL</b> (Feld Hellschreiber) is read straight off the screen. <b>SSTV</b> receives pictures; it starts on its own when a picture begins, or press ▶ START NOW. 📷 PICK A PHOTO or 🪪 MY CARD sends one. Sending in any mode needs your real call sign. PSK31 and WSPR are not in this version.' },
    { id: 'uploads', s: 'log', t: '☁ Uploads (QRZ, eQSL, Wavelog)', k: 'upload uploads qrz eqsl wavelog logbook api key send cloud', h: '<b>☁ UPLOADS</b> sends each new contact to QRZ Logbook, eQSL or Wavelog by itself. Turn a service ON and put in its key (for QRZ, the logbook\'s API key from the QRZ website). Each contact shows ☁ when it went up, or ⚠ with the reason when it did not. No signal? The contacts wait and go up when the signal is back. A contact you fix later is sent again. LoTW and POTA are not sent from here: use ✅ CHECK &amp; SAVE FOR POTA for the POTA file.' },
    { id: 'alerts', s: 'station', t: '🔔 Alerts', k: 'alerts alert notification buzz watchlist park closure weather lightning space calling clock', h: 'STATION → Alerts. The app can tell you when a friend on your watchlist is on the air, a park you need is spotted (and whether your radio can hear it), a park is closed, there is a weather or lightning warning near you, a space-weather storm is on, someone is calling you on FT8, your clock is off, or the radio may still be transmitting. Each kind has its own switch. An alert is a message on the screen, a buzz on a phone, and a notification that reaches you with the screen off. The last 100 are kept in the list. 🔔 TEST AN ALERT tries it.' },
    { id: 'about', s: 'station', t: '📜 About and licences', k: 'about licence license licences notices open source ft8_lib codec2 natural earth credits', h: 'The KPC app is made by the Kentucky Portable Club. Three parts come from other people and are used under their licences: the FT8 / FT4 decoder <b>ft8_lib</b> (Karlis Goba, MIT licence), the FreeDV digital voice library <b>codec2</b> (David Rowe and the FreeDV project, LGPL 2.1: you may rebuild it and put your own copy in its place), and the built-in world map from <b>Natural Earth</b> (public domain). The full texts are in the app\'s <a href="notices/README.txt" target="_blank" rel="noopener">notices</a> folder.' }
  ];
  /* ================================================================ RADIO SETUP: what each radio's own menus need (adds to kpc-app's family tips) */
  const MODEL = {
    ic7300: ['MENU → SET → Connectors → CI-V: CI-V Baud Rate = 115200 (or Auto), CI-V Address = 94h, CI-V Transceive = ON, CI-V USB Port = Unlink from [REMOTE], CI-V USB Baud Rate = 115200, CI-V USB Echo Back = OFF', 'Connectors → MOD Input → DATA MOD = USB · USB MOD Level about 50 %', 'Connectors → ACC/USB Output Select = AF · USB AF Output Level about 50 %', 'For the RF scope under the band maps: Connectors → CI-V → CI-V USB Port must be Unlink from [REMOTE]', 'Windows driver: Icom\'s "USB driver" (Silicon Labs CP210x)'],
    ic705: ['MENU → SET → Connectors → CI-V: CI-V Address = A4h, CI-V USB Port = Unlink from [REMOTE], CI-V USB Echo Back = OFF', 'Connectors → MOD Input → DATA MOD = USB', 'USB AF / SQL Output → AF Output Level about 50 %', 'Bluetooth CAT is not used by the app: use the USB cable'],
    ic7100: ['MENU → SET → Connectors → CI-V: CI-V Baud Rate = 19200, CI-V Address = 88h, CI-V USB Echo Back = OFF', 'Connectors → DATA MOD = USB', 'Connectors → USB Audio SQL = OFF (OPEN), USB MOD Level about 50 %', 'The IC-7100 has no RF scope over CAT: the app shows the AUDIO picture'],
    ic9700: ['MENU → SET → Connectors → CI-V: CI-V Address = A2h, CI-V USB Port = Unlink from [REMOTE], CI-V USB Baud Rate = 115200, Echo Back = OFF', 'Connectors → MOD Input → DATA MOD = USB'],
    ic7610: ['MENU → SET → Connectors → CI-V: CI-V Address = 98h, CI-V USB (A) Port = Unlink from [REMOTE], USB (A) Baud = 115200, Echo Back = OFF', 'Connectors → MOD Input → DATA MOD = USB'],
    ft710: ['MENU → OPERATION SETTING → GENERAL: CAT-1 RATE = 38400, CAT-1 TIME OUT TIMER = 10 ms (or longer)', 'The radio makes two COM ports: the ENHANCED one is CAT, the STANDARD one is the PTT / keying line', 'MENU → OPERATION SETTING → MODE PSK/DATA (DATA): DATA MOD SOURCE = REAR, REAR SELECT = USB, USB MOD GAIN about 50', 'MODE SSB: SSB MOD SOURCE = REAR for voice from the app (or let the app switch to DATA while it sends)', 'The FT-710 scope over USB needs Yaesu\'s own driver: the app shows the AUDIO picture instead'],
    ftdx10: ['MENU → OPERATION SETTING → GENERAL: CAT RATE = 38400, CAT TIME OUT TIMER = 10 ms or longer', 'ENHANCED COM port = CAT, STANDARD = PTT / keying', 'MODE PSK/DATA: DATA MOD SOURCE = REAR, REAR SELECT = USB, USB MOD GAIN about 50', 'MODE SSB: SSB MOD SOURCE = REAR for voice from the app'],
    ftdx101: ['MENU → OPERATION SETTING → GENERAL: CAT RATE = 38400', 'ENHANCED COM port = CAT', 'MODE PSK/DATA: DATA MOD SOURCE = REAR, REAR SELECT = USB'],
    ftx1: ['MENU → CAT: CAT-1 RATE = 38400', 'ENHANCED COM port = CAT, STANDARD = PTT / keying', 'STATION → FTX-1: WHAT IS IT PLUGGED INTO: pick the SPA-1 amplifier if it is on, so the POWER slider works in the right watts', 'DATA mode: MOD SOURCE = REAR (USB), USB MOD GAIN about 50', 'Not checked on a real FTX-1 yet: please send a WORKS ON MY RADIO report'],
    ft891: ['MENU 05-06 CAT RATE = 38400, 05-08 CAT RTS = DISABLE (or let the app hold RTS)', 'The FT-891 has no USB sound card: use a Digirig, SCU-17 or similar on the DATA jack', 'DATA menu: DATA IN SELECT = REAR, DATA PTT SELECT = RTS (Digirig) or DAKY', 'With an SCU-17: CAT on the ENHANCED port, PTT on the STANDARD port'],
    ft991: ['MENU 031 CAT RATE = 38400, 032 CAT TOT = 10 ms or longer, 033 CAT RTS = DISABLE', 'MENU 070 DATA IN SELECT = REAR, 071 DATA PTT SELECT = RTS, 073 DATA OUT LEVEL about 50', 'ENHANCED COM port = CAT, STANDARD = PTT', 'Mode: DATA-U for FT8'],
    ts590: ['MENU: COM / USB port baud = 115200 (USB) — match the app', 'MENU: audio source for DATA = USB, USB audio input level about 5, DATA VOX = OFF', 'Use DATA (DA1) mode for FT8'],
    ts890: ['MENU → Advanced: USB (virtual COM) baud = 115200', 'Audio source for DATA mode = USB audio', 'Use DATA mode for FT8'],
    kx3: ['CONFIG: RS232 = 38400, AUTOINF = NOR', 'DATA A mode; MIC/LINE input = LINE IN from the sound card (KXUSB + a USB sound card, or a Digirig)'],
    k4: ['MENU: RS232 / USB baud = 38400 (the K4 USB port also works at higher rates)', 'DATA mode: TX audio from USB (LINE IN) — the K4 has its own USB audio'],
    g90: ['CI-V address 70h, baud 19200 (the G90 default)', 'Needs the Xiegu DE-19 (or a Digirig) for sound: the G90 has no USB sound card', 'PTT by CAT or by the DE-19\'s PTT line'],
    qmx: ['QMX menu: CAT = Kenwood TS-480 style (always on), any baud', 'USB sound card built in: pick "QMX" as the sound card', 'USB SERIAL PORTS = 3: CAT on the lowest-numbered port']
  };
  /* ================================================================ TROUBLESHOOTER */
  const TRB = [
    ['The radio does not answer (CONNECT fails)', ['Is the right radio picked in STATION → MY RADIO? The baud rate there must match the radio\'s own CAT / CI-V baud menu.', 'Close every other radio program (WSJT-X, flrig, N1MM, the radio maker\'s tool): only one program can hold the port.', 'Pick the right port: ⚙ MORE RADIO SETTINGS → PICK A DIFFERENT PORT. Yaesu with two ports: the ENHANCED one. Icom: the CP210x one.', 'Yaesu that only answers with its CAT RTS menu ON: the app tries that by itself only on the radio\'s own USB port. On any other cable, pick the port by hand once (it is remembered), or set the radio\'s CAT RTS menu to DISABLE.', 'Icom: the CI-V address in the app must match the radio (7300 = 94h, 705 = A4h, 7100 = 88h, 9700 = A2h), and CI-V USB Echo Back = OFF.', 'Unplug the USB cable, wait 5 seconds, plug it back in, CONNECT again.', 'Still nothing: try HOW THE APP REACHES IT = Hamlib rigctld or flrig.']],
    ['Frequency works but there is no sound / no decodes', ['STATION → SOUND: pick the radio\'s own USB sound card (USB Audio CODEC on Icom / Yaesu) as the input and press START.', 'The level bar should move: aim for the middle. Too low: raise the radio\'s USB AF output level. Too high: lower it.', 'The radio must be in DATA-U / USB-D for FT8, on the right frequency, with the filter at least 2.4 kHz wide.', 'Check the clock: FT8 needs the PC / phone clock within a second (the clock at the top turns red when it is off).']],
    ['It transmits but no power out', ['The radio\'s DATA MOD source must be USB / REAR (see the setup guide for your radio).', 'Raise the app\'s TX level until ALC barely moves; ALC pinned = too much.', 'Check RF POWER on the RADIO screen and that the radio is in DATA-U, not USB with the mic as the source.']],
    ['PTT does not key the radio', ['STATION → how the radio is keyed: CAT for most USB radios; RTS / DTR for a Digirig or SCU-17; VOX as the last resort.', 'Yaesu: CAT RTS menu = DISABLE if the radio keys when the app opens the port, or ENABLE if it never keys by RTS.', 'Make sure your call sign is set: the app will not transmit without it.']],
    ['A 🎛 MORE CONTROLS button does nothing', ['Some models answer a command a little differently: the app only knows what the maker\'s manual says.', 'Send a 📝 WORKS ON MY RADIO report so it can be fixed (or hidden) for your radio.', 'With Hamlib rigctld: Hamlib decides what your radio takes; unsupported ones are ignored.']],
    ['⚠ HIGH SWR warning', ['Stop and check the antenna, the coax and the connectors.', 'Press 🔧 TUNE if the radio has a tuner (it asks first), then try again.', 'The guard reads the radio\'s own SWR meter: if it warns at a good match, raise the limit (🎛 MORE CONTROLS → Safety).']],
    ['The RF scope is empty', ['Only the Icom IC-7300 / 705 / 9700 / 7610 / 905 send their scope over CAT.', 'Icom: CI-V USB Port = Unlink from [REMOTE]; the radio\'s scope display must be on.', 'Other radios: pick AUDIO for the picture from the sound card.']],
    ['No spots / skimmers', ['Spots need internet. On the Field Day site with no internet they come back when you have it.', 'Skimmers (RBN) on Windows log in with your call sign; on a phone they come through Spothole.']],
    ['Contest: dupes or score look wrong', ['Make sure the CONTEST log is the one open (the 🏆 tab says ✓ CONTEST LOG IS OPEN) and the year is right.', 'A contact logged in another log does not count: move it from MY LOGS.', 'Load CTY.DAT for DX contests (countries and zones).']],
    ['The phone cannot reach the PC', ['Same Wi-Fi, or Tailscale on both when away from home.', 'Pair again with a fresh code from the PC.', 'Windows firewall: allow the KPC app on private networks.']]
  ];

  /* ================================================================ the ❓ in the top bar + the HELP screen */
  const look = $('look');
  if (look && !$('helpBtn')) look.insertAdjacentHTML('beforebegin', '<button type="button" class="ic" id="helpBtn" aria-label="Help for this screen" title="Help">❓</button>');
  const main = document.querySelector('main');
  if (main && !$('scrHelp')) main.insertAdjacentHTML('beforeend', '<section class="scr" id="scrHelp" aria-label="Help"><div id="hpBody"></div></section>');
  const st = document.createElement('style'); st.textContent = '.hpg{margin:14px 0 4px;font:800 12px var(--sans);letter-spacing:.08em;color:var(--goldT)}.hpg:first-of-type{margin-top:2px}.hpsteps{margin:0;padding-left:22px}.hpsteps li{margin:0 0 10px;line-height:1.45}.hpsteps .b{margin:4px 4px 0 0;vertical-align:middle}body[data-screen="help"] #scrHelp{display:block}#scrHelp{max-width:980px;margin:0 auto}#helpBtn{font-size:16px}.hpq{width:100%;height:46px;font-size:17px;margin:0 0 10px}.hpt{margin:0 0 8px}.hpt summary{cursor:pointer;font-weight:700;padding:8px 0}.hpt p{margin:4px 0 10px}.helpl{margin:6px 0 10px 18px;padding:0}.helpl li{margin:4px 0}.hpw{display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin:6px 0}.hpw .k{flex:1 1 200px}.hptab{width:100%;border-collapse:collapse;font-size:13px}.hptab td,.hptab th{border-bottom:1px solid var(--line);padding:5px 4px;text-align:left;vertical-align:top}.hpok{color:var(--ok)}.hpbad{color:var(--red)}.wzs{font:700 11px var(--sans);letter-spacing:.12em;color:var(--goldT)}';
  document.head.appendChild(st);
  $('helpBtn') && ($('helpBtn').onclick = () => screenHelp(document.body.dataset.screen || 'log'));
  function screenHelp(s) {
    const list = T.filter(t => t.s === s || (s === 'logs' && t.id === 'log')).concat(T.filter(t => t.a && t.s !== s));   /* a: 1 = on every screen (ON AIR / STOP ALL) */
    AP.sheet('❓ Help' + (list[0] ? ': ' + list[0].t : ''), (list.length ? list.map(t => `<h3>${esc(t.t)}</h3><p>${t.h}</p>`).join('') : '<p>Pick a topic on the HELP page.</p>') +
      `<div class="row"><button type="button" class="b gold" id="hpAll">📖 ALL HELP</button>${K ? '<button type="button" class="b" id="hpWiz">🧙 RADIO SETUP WIZARD</button>' : ''}<button type="button" class="b" id="hpTrb">🩺 SOMETHING NOT WORKING</button></div>`);
    $('hpAll').onclick = () => { AP.shut(); open(); };
    if ($('hpWiz')) $('hpWiz').onclick = () => { AP.shut(); wizard(); };
    $('hpTrb').onclick = () => { AP.shut(); open('trb'); };
  }
  /* Nov 10 (Brandon: 'the help page ... very user friendly'): topics under the screen they belong to, and a GETTING STARTED card */
  const SCR = [['', '⭐ The basics'], ['logs', '📒 My logs'], ['log', '📋 LOG'], ['digi', '📶 DIGI (FT8 and the other modes)'], ['spots', '📍 SPOTS'], ['radio', '📻 RADIO'], ['map', '🗺 MAP'], ['station', '⚙ STATION (settings)'], ['contest', '🏆 Contesting'], ['remote', '🔗 Remote']];
  const START = () => `<section class="card hpstart"><h2>🚀 Getting started</h2><ol class="hpsteps">
      <li><b>Your call sign and grid.</b> STATION → 👤 ME. They go in every log entry and every FT8 message. <button type="button" class="b sm" data-hgo="station:me:stCall">OPEN</button></li>
      <li><b>Your radio.</b> The wizard walks you through the radio's menus, the cable and CONNECT. <button type="button" class="b gold sm" id="hpWiz3">🧙 START THE WIZARD</button></li>
      <li><b>The sound</b> (FT8 and the digital modes only): pick the radio's USB sound in STATION → 📻 RADIO & SOUND. <button type="button" class="b sm" data-hgo="station:radio:stIn">OPEN</button></li>
      <li><b>Log a contact.</b> Type the call at the bottom of LOG and press the gold ⬆. Tapping a spot fills it in for you. <button type="button" class="b sm" data-hgo="log">LOG</button> <button type="button" class="b sm" data-hgo="spots">SPOTS</button></li>
      <li><b>FT8.</b> DIGI → START, then tap a station to call it. <button type="button" class="b sm" data-hgo="digi">DIGI</button></li></ol>
      <p class="hint">Stuck? 🩺 <b>Something not working?</b> is further down, and STATION → ❓ HELP → COPY A REPORT FOR THE BUILDERS sends us what we need.</p></section>`;
  let Q = '';
  function open(part) { AP.go('help'); $('ttl').textContent = 'Help'; draw(); if (part) setTimeout(() => { const e = $('hp_' + part); if (e) { if (e.tagName === 'DETAILS') e.open = true; e.scrollIntoView({ block: 'start' }); } }, 60); }
  function draw() {
    const b = $('hpBody'); if (!b) return;
    const q = Q.toLowerCase().trim(), hit = t => !q || (t.t + ' ' + t.k + ' ' + t.h.replace(/<[^>]+>/g, '')).toLowerCase().includes(q);
    const th = T.filter(hit), tr = TRB.filter(([a, l]) => !q || (a + ' ' + l.join(' ')).toLowerCase().includes(q));
    b.innerHTML = `<input class="hpq" id="hpQ" type="search" placeholder="🔎 Search the help (try: ft8 sound, split, swr, field day)" value="${esc(Q)}">
      <div class="row"><button type="button" class="b gold" id="hpWiz2">🧙 RADIO SETUP WIZARD</button><button type="button" class="b" id="hpWorks">📝 WORKS ON MY RADIO</button><button type="button" class="b" id="hpBack">‹ BACK</button></div>
      ${q ? '' : START()}
      <section class="card"><h2>How things work</h2>${SCR.map(([s, lab]) => { const L = th.filter(t => (t.s || '') === s); return L.length ? `<h3 class="hpg">${lab}</h3>` + L.map(t => `<details class="hpt" id="hp_${t.id}"${q ? ' open' : ''}><summary>${esc(t.t)}</summary><p>${t.h}</p></details>`).join('') : ''; }).join('') || '<p class="hint">Nothing matches.</p>'}</section>
      <section class="card" id="hp_trb"><h2>🩺 Something not working?</h2>${tr.map(([a, l], i) => `<details class="hpt"${q ? ' open' : ''}><summary>${esc(a)}</summary><ol class="helpl">${l.map(x => '<li>' + esc(x) + '</li>').join('')}</ol></details>`).join('') || '<p class="hint">Nothing matches.</p>'}</section>
      ${K ? `<section class="card" id="hp_guide"><h2>📖 Setting up your radio</h2><label class="e">WHICH RADIO<select id="hpRig"></select></label><div id="hpGuide"></div></section>
      <section class="card" id="hp_radios"><h2>📻 Radios and what they take</h2><p class="hint">✓ = checked on a real radio with KPC. Everything else follows the maker's CAT manual and has not been tried on the air yet: a 📝 WORKS ON MY RADIO report gets it checked.</p><div id="hpRadios"></div></section>` : ''}`;
    const qi = $('hpQ'); qi.oninput = () => { Q = qi.value; const p = qi.selectionStart; draw(); const n = $('hpQ'); n.focus(); try { n.setSelectionRange(p, p); } catch (e) {} };
    b.querySelectorAll('[data-hgo]').forEach(x => { x.onclick = () => { const [scr, grp, el] = x.dataset.hgo.split(':'); AP.go(scr); if (grp && G.KPCTidy) KPCTidy.show(grp); if (el) setTimeout(() => { const e = $(el); if (e) { e.scrollIntoView({ block: 'center' }); if (e.focus) e.focus(); } }, 120); }; });
    if ($('hpWiz3')) $('hpWiz3').onclick = () => wizard();
    $('hpWiz2').onclick = () => wizard(); $('hpWorks').onclick = () => works(); $('hpBack').onclick = () => AP.go(LAST || 'log');
    if (K) { K.fillSelect($('hpRig')); $('hpRig').value = K.get().radio || ''; $('hpRig').onchange = () => { $('hpGuide').innerHTML = guideHtml($('hpRig').value); }; $('hpGuide').innerHTML = guideHtml($('hpRig').value); radios(); }
  }
  function guideHtml(id) {
    if (!K) return '';
    const R = K.RADIO[id], tips = AP.rigTips ? AP.rigTips() : {}, fam = AP.rigFam ? AP.rigFam(id) : 'other', F = tips[fam];
    if (!id) return '<p class="hint">Pick your radio for its setup guide.</p>';
    const C = K.caps ? K.caps(id) : null, keys = C ? C.keys : [];
    return (R ? `<p><b>${esc(R.label)}</b> · CAT ${esc(R.proto === 'icom' ? 'CI-V' : R.proto === 'kenwood' ? 'Kenwood-style' : 'Yaesu')} at <b>${R.baud}</b> baud${R.civ ? ' · CI-V address <b>' + esc(R.civ) + 'h</b>' : ''}</p>` : '') +
      (MODEL[id] ? '<h3>On this radio</h3><ul class="helpl">' + MODEL[id].map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '') +
      (F ? '<h3>' + esc(F[0]) + '</h3><ul class="helpl">' + F[1].map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>' : '') +
      `<p class="hint">🎛 Controls the app can send to it: ${keys.length ? keys.map(k => NAMES[k] || k).join(', ') : 'frequency, mode and the basics only'}.${WORKS[id] ? ' · 📝 your report from ' + esc(WORKS[id].date) : ''}</p>`;
  }
  const NAMES = { shift: 'IF shift', nrl: 'NR level', nbl: 'NB level', agc: 'AGC', att: 'ATT', pre: 'preamp', contour: 'contour', apf: 'APF', mnotch: 'manual notch', mnotchf: 'notch frequency', split: 'split', rit: 'RIT', xit: 'XIT', ritoff: 'RIT offset', swap: 'A⇄B', ab: 'A=B', keyspd: 'keyer speed', bkin: 'break-in' };
  function radios() {
    const el = $('hpRadios'); if (!el || !K) return;
    el.innerHTML = '<table class="hptab"><tr><th>RADIO</th><th>MORE CONTROLS</th><th>CHECKED</th></tr>' + K.RADIOS.map(([g, L]) => L.map(r => { const id = r[0], C = K.caps(id), w = WORKS[id], t = K.TESTED[id];
      return `<tr><td>${esc((K.RADIO[id] || {}).label || r[1])}</td><td>${C.keys.length}</td><td>${t ? '<span class="hpok">✓ ' + esc(t.date || '') + '</span>' : w ? '<span class="' + (w.bad.length ? 'hpbad' : 'hpok') + '">📝 your report: ' + w.ok.length + ' ok' + (w.bad.length ? ', ' + w.bad.length + ' not' : '') + '</span>' : 'not yet'}</td></tr>`; }).join('')).join('') + '</table>';
  }
  function guide(id) { open('guide'); setTimeout(() => { const s = $('hpRig'); if (s && id) { s.value = id; $('hpGuide').innerHTML = guideHtml(id); } }, 80); }
  let LAST = 'log';
  AP.on('screen', s => { if (s !== 'help') LAST = s; else { $('ttl').textContent = 'Help'; draw(); } });

  /* ================================================================ 🧙 RADIO SETUP WIZARD */
  function wizard(step) {
    if (!K) return; step = step || 1; const c = K.get(), id = c.radio || '';
    const head = n => `<p class="wzs">STEP ${n} OF 5</p>`;
    if (step === 1) {
      AP.sheet('🧙 Radio setup', head(1) + '<p>Which radio is it?</p><label class="e wide">MY RADIO<select id="wzRig"></select></label><div class="row"><button type="button" class="b gold" id="wzN">NEXT ›</button></div>');
      K.fillSelect($('wzRig')); $('wzRig').value = id;
      $('wzN').onclick = () => { const v = $('wzRig').value; if (!v) { AP.toast('Pick the radio first.', 2500, 'bad'); return; } K.pickRadio(v); K.set({ on: true }); const s = $('stRig'); if (s) s.value = v; wizard(2); };
    } else if (step === 2) {
      AP.sheet('🧙 Set the radio\'s menus', head(2) + guideHtml(id) + '<div class="row"><button type="button" class="b" id="wzB">‹ BACK</button><button type="button" class="b gold" id="wzN">DONE, NEXT ›</button></div>');
      $('wzB').onclick = () => wizard(1); $('wzN').onclick = () => wizard(3);
    } else if (step === 3) {
      AP.sheet('🧙 Plug in and connect', head(3) + '<p>Turn the radio on and plug the USB cable into this device. Close other radio programs. Then press CONNECT and pick the radio\'s port when asked.</p><div class="row"><button type="button" class="b" id="wzB">‹ BACK</button><button type="button" class="b gold" id="wzC">📻 CONNECT</button></div><p class="hint" id="wzSt"></p>');
      $('wzB').onclick = () => wizard(2);
      $('wzC').onclick = async () => { $('wzSt').textContent = 'Connecting…'; const b = $('stConn'); if (b) b.click(); else await K.connect(true);
        let ok = false; for (let i = 0; i < 20 && !ok; i++) { await new Promise(r => setTimeout(r, 500)); ok = K.connected(); }
        if (ok) wizard(4); else { const m = (AP.catMsg && AP.catMsg()) || {}; $('wzSt').innerHTML = '❌ ' + esc(m.t || 'The radio did not answer.') + ' <button type="button" class="chip" id="wzT">🩺 HELP ME</button>'; $('wzT').onclick = () => { AP.shut(); open('trb'); }; } };
    } else if (step === 4) {
      AP.sheet('🧙 Does it match?', head(4) + '<p>The radio says:</p><p class="cxbig" id="wzF">…</p><p>Is that what the radio\'s display shows?</p><div class="row"><button type="button" class="b gold" id="wzY">✓ YES</button><button type="button" class="b" id="wzNo">✗ NO</button></div>');
      K.read().then(r => { $('wzF').textContent = r && r.khz ? (r.khz / 1000).toFixed(3) + ' MHz ' + (r.mode || '') : 'no answer'; });
      $('wzY').onclick = () => wizard(5); $('wzNo').onclick = () => { AP.shut(); open('trb'); };
    } else {
      AP.sheet('🧙 Sound, then done', head(5) + '<p>Last thing: in STATION → SOUND pick the radio\'s USB sound card (USB Audio CODEC on Icom and Yaesu) and press START. The level bar should sit in the middle.</p><p>✓ The radio is set up. Try the 📻 RADIO screen: 🎛 MORE CONTROLS shows what this radio takes.</p><div class="row"><button type="button" class="b gold" id="wzSnd">🔊 SOUND SETTINGS</button><button type="button" class="b" id="wzR">📻 RADIO SCREEN</button><button type="button" class="b" id="wzW">📝 REPORT HOW IT WENT</button></div>');
      $('wzSnd').onclick = () => { AP.shut(); AP.go('station'); const d = $('stDev'); if (d) d.scrollIntoView({ block: 'center' }); };
      $('wzR').onclick = () => { AP.shut(); AP.go('radio'); }; $('wzW').onclick = () => works();
    }
  }

  /* ================================================================ 📝 WORKS ON MY RADIO */
  const BASIC = [['freq', 'Frequency read + set'], ['mode', 'Mode (USB / LSB / CW / DATA)'], ['ptt', 'Transmit (PTT)'], ['meters', 'Meters (S, power, SWR, ALC)'], ['width', 'Filter width'], ['nb', 'NB on / off'], ['nr', 'NR on / off'], ['notch', 'Auto notch'], ['power', 'RF power'], ['mic', 'Mic gain'], ['atu', '🔧 Tune'], ['cw', 'CW typed from the app'], ['scope', 'RF scope'], ['onoff', 'Radio on / off']];
  function works() {
    if (!K) return; const c = K.get(), id = c.radio || '', R = K.RADIO[id];
    if (!id) { AP.toast('Pick your radio first (STATION → MY RADIO).', 3000, 'bad'); return; }
    const C = K.caps(id), list = BASIC.concat(C.keys.map(k => [k, NAMES[k] || k])), prev = WORKS[id] || { ok: [], bad: [] }, val = {};
    list.forEach(([k]) => { val[k] = prev.ok.includes(k) ? 1 : prev.bad.includes(k) ? -1 : 0; });
    AP.sheet('📝 Works on my ' + (R ? R.label : 'radio'), '<p class="hint">Try each one on the radio, then tap ✓ or ✗. Leave the ones you did not try.</p>' +
      list.map(([k, l]) => `<div class="hpw"><span class="k">${esc(l)}</span><button type="button" class="chip" data-wk="${k}" data-wv="1">✓ WORKS</button><button type="button" class="chip" data-wk="${k}" data-wv="-1">✗ NOT</button></div>`).join('') +
      '<label class="e wide">NOTES (firmware, cable, what went wrong)<textarea id="wkN" rows="3">' + esc(prev.note || '') + '</textarea></label><div class="row"><button type="button" class="b gold" id="wkGo">📤 SEND / SAVE THE REPORT</button></div>');
    const paint = () => document.querySelectorAll('[data-wk]').forEach(b => b.classList.toggle('on', val[b.dataset.wk] === +b.dataset.wv));
    paint(); document.querySelectorAll('[data-wk]').forEach(b => { b.onclick = () => { const k = b.dataset.wk, v = +b.dataset.wv; val[k] = val[k] === v ? 0 : v; paint(); }; });
    $('wkGo').onclick = async () => {
      const rep = { radio: id, label: R ? R.label : id, ok: list.filter(([k]) => val[k] === 1).map(([k]) => k), bad: list.filter(([k]) => val[k] === -1).map(([k]) => k), note: $('wkN').value.trim(), date: new Date().toISOString().slice(0, 10), link: K.link ? K.link() : '', ver: AP.VER };
      WORKS[id] = rep; SV('kpcAppWorks', WORKS);
      const me = AP.me ? (AP.me().call || '') : '';
      const txt = `KPC app — WORKS ON MY RADIO\nRadio: ${rep.label} (${id})\nApp: ${rep.ver || ''} · link: ${rep.link}\nBy: ${me}\nDate: ${rep.date}\n\nWORKS: ${rep.ok.map(k => NAMES[k] || k).join(', ') || '-'}\nDOES NOT WORK: ${rep.bad.map(k => NAMES[k] || k).join(', ') || '-'}\nNotes: ${rep.note || '-'}\n`;
      AP.shut();
      let done = false;
      try { if (navigator.share) { await navigator.share({ title: 'KPC: works on my ' + rep.label, text: txt }); done = true; } } catch (e) {}
      if (!done) { try { await navigator.clipboard.writeText(txt); AP.toast('📝 Report copied: paste it to the club (email, Discord, GitHub).', 5000, 'log'); done = true; } catch (e) {} }
      if (!done && AP.saveFile) AP.saveFile(txt, 'KPC-works-' + id + '-' + rep.date + '.txt', 'text/plain');
      if (document.body.dataset.screen === 'help') draw();
    };
  }

  G.KPCHelp = { open, draw, screenHelp, wizard, works, guide, guideHtml, topics: T, trouble: TRB, models: MODEL, reports: WORKS };
})(window);
